      ta: ['மரம் வெட்டுதல் எட்டாத ஆதி மழைக்காடு', 'கிராமங்களிலிருந்து சுமார் ஒரு மணி நேர நடையில் உள்ள தெகிவிட் நீர்வீழ்ச்சி', 'பாத்தேயு லாயுக் சிகரமும் பாத்தேயு சிமான் குகையும்', 'வெளி இயக்குநர் அல்ல, சமூகங்களே நடத்தும் தங்குமிடங்கள்'],
      ar: ['غابة مطيرة أولية لم يبلغها قطع الأشجار', 'شلال تيكيويت، على نحو ساعة سيرًا من القرى', 'قمة باتيو لايوك وكهف باتيو سيمان', 'إقامات تديرها المجتمعات نفسها لا مشغّل خارجي'],
